package com.example.fastorder

import android.os.SystemClock
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * Where the first screen should land once startup work is done.
 *
 * Deciding this *before* the splash is dismissed is the whole point of holding
 * it - it avoids showing Home for a frame and then yanking the user to sign-in.
 */
enum class StartDestination {
    Home,
    Onboarding,
    SignIn,
}

/**
 * Immutable snapshot of app startup.
 *
 * @param isReady false while startup work is in flight; the splash stays up.
 * @param startDestination where to navigate once [isReady] is true.
 */
data class MainUiState(
    val isReady: Boolean = false,
    val startDestination: StartDestination = StartDestination.Home,
)

/**
 * Owns app-startup state.
 *
 * Lives in a ViewModel rather than the Activity so it survives configuration
 * changes - rotating the device mid-startup must not restart the work or
 * re-show the splash.
 */
class MainViewModel : ViewModel() {

    private val _uiState = MutableStateFlow(MainUiState())
    val uiState: StateFlow<MainUiState> = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            val startedAt = SystemClock.uptimeMillis()

            // TODO: real startup work - restore the Firebase Auth session, warm
            //  the Firestore catalog cache, fetch Remote Config. The result
            //  decides startDestination (Home vs Onboarding vs SignIn).

            // The system splash no longer needs padding to be seen - the in-app
            // BrandSplashScreen provides the branded moment now, and it runs in
            // parallel with this work. Keep this at 0 so the system splash
            // lasts exactly as long as startup actually takes.
            val elapsed = SystemClock.uptimeMillis() - startedAt
            if (elapsed < MIN_SPLASH_VISIBLE_MS) {
                delay(MIN_SPLASH_VISIBLE_MS - elapsed)
            }

            _uiState.value = MainUiState(
                isReady = true,
                startDestination = StartDestination.Home,
            )
        }
    }

    private companion object {
        const val MIN_SPLASH_VISIBLE_MS = 0L
    }
}

package com.example.fastorder.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.example.fastorder.StartDestination
import com.example.fastorder.ui.screens.HomeScreen
import com.example.fastorder.ui.screens.OnboardingScreen
import com.example.fastorder.ui.screens.SignInScreen

/**
 * The app's single navigation graph, hosted by MainActivity.
 *
 * [startDestination] is resolved by MainViewModel *before* the splash is
 * dismissed, so the user never sees Home flash before being sent to sign-in.
 */
@Composable
fun FastOrderNavHost(
    startDestination: StartDestination,
    modifier: Modifier = Modifier,
    navController: NavHostController = rememberNavController(),
) {
    NavHost(
        navController = navController,
        startDestination = startDestination.toRoute(),
        modifier = modifier,
    ) {
        composable<Route.Onboarding> {
            OnboardingScreen(
                onFinished = { navController.replaceGraphWith(Route.SignIn) },
            )
        }
        composable<Route.SignIn> {
            SignInScreen(
                onSignedIn = { navController.replaceGraphWith(Route.Home) },
            )
        }
        composable<Route.Home> {
            HomeScreen()
        }
    }
}

private fun StartDestination.toRoute(): Route = when (this) {
    StartDestination.Home -> Route.Home
    StartDestination.Onboarding -> Route.Onboarding
    StartDestination.SignIn -> Route.SignIn
}

/**
 * Navigates to [route] and clears everything behind it.
 *
 * Used for one-way transitions (onboarding -> sign-in -> home) so pressing back
 * from Home exits the app instead of returning to the sign-in screen.
 */
private fun NavHostController.replaceGraphWith(route: Route) {
    navigate(route) {
        popUpTo(graph.id) { inclusive = true }
        launchSingleTop = true
    }
}

package com.example.fastorder.ui.navigation

import kotlinx.serialization.Serializable

/**
 * Type-safe navigation routes.
 *
 * These are destinations *inside* the single MainActivity - not Activities.
 * Sign-in is a screen you navigate to and pop off the back stack, exactly like
 * any other screen, which is what lets it share a NavController, survive
 * process death, and participate in deep links.
 *
 * Objects are used for argument-less screens; use @Serializable data classes
 * when a route needs arguments, e.g.
 *
 *     @Serializable data class ProductDetail(val productId: String) : Route
 */
sealed interface Route {

    /** First-run product tour. Shown only when the user has never opened the app. */
    @Serializable
    data object Onboarding : Route

    /** Authentication. Reachable mid-session too, e.g. after a forced sign-out. */
    @Serializable
    data object SignIn : Route

    /** Catalog home - the storefront. */
    @Serializable
    data object Home : Route
}

