#!/usr/bin/expect -f
# Drives `firebase login:add --no-localhost` through a PTY.
# Phase 1: capture the login URL into /tmp/fblogin_raw.log
# Phase 2: poll /tmp/fbcode.txt for the auth code, then submit it.

set timeout -1
log_file /tmp/fblogin_raw.log

spawn npx -y firebase-tools@latest login:add --no-localhost

expect {
    -re "(collect CLI|usage and error reporting)" {
        send -- "n\r"
        exp_continue
    }
    -re "(Paste authorization code|authorization code here)" {
        # prompt reached, fall through
    }
}

# Wait for the operator to drop the auth code into /tmp/fbcode.txt
set code ""
while {$code eq ""} {
    if {[file exists "/tmp/fbcode.txt"]} {
        set fh [open "/tmp/fbcode.txt" r]
        set code [string trim [read $fh]]
        close $fh
    }
    if {$code eq ""} {
        sleep 2
    }
}

send -- "$code\r"
expect eof

#!/usr/bin/expect -f
# Drives `firebase login:add` using the DEFAULT localhost redirect flow.
# This talks straight to accounts.google.com and avoids the
# auth.firebase.tools attestation proxy that returns "Unable to verify client".
# No auth code to paste - the CLI receives the callback on localhost itself.

set timeout -1
log_file /tmp/fblogin2.log

spawn npx -y firebase-tools@latest login:add

expect {
    -re "(collect CLI|usage and error reporting)" {
        send -- "n\r"
        exp_continue
    }
    eof {
        # login finished (success or failure); log has the detail
    }
}
